#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>

// a.size()는 실제 원소 n개와 비어 있는 뒤쪽 m칸을 합친 크기입니다.
void mergeBack(std::vector<int>& a, int n, const std::vector<int>& b) {
    const int m = static_cast<int>(b.size());
    assert(n >= 0 && a.size() == static_cast<std::size_t>(n + m));
    int i = n - 1, j = m - 1, write = n + m - 1;
    // 뒤에서 큰 값을 확정하면 아직 읽지 않은 a의 앞부분을 덮지 않습니다.
    while (j >= 0) {
        if (i >= 0 && a[i] > b[j]) {
            a[write--] = a[i--];
        } else {
            a[write--] = b[j--];
        }
    }
    // b를 모두 썼다면 남은 a의 앞부분은 이미 제자리에 있습니다.
}

void generate(int remaining, int minimum, std::vector<int>& cur,
              std::vector<std::vector<int>>& all) {
    if (remaining == 0) { all.push_back(cur); return; }
    for (int value = minimum; value <= 2; ++value) {
        cur.push_back(value);
        generate(remaining - 1, value, cur, all);
        cur.pop_back();
    }
}
int main() {
    std::vector<std::vector<int>> sorted;
    std::vector<int> cur;
    for (int size = 0; size <= 5; ++size) generate(size, -2, cur, sorted);
    long long cases = 0;
    for (const auto& left : sorted) for (const auto& right : sorted) {
        std::vector<int> actual = left;
        actual.resize(left.size() + right.size());
        std::vector<int> expected = left;
        expected.insert(expected.end(), right.begin(), right.end());
        std::sort(expected.begin(), expected.end());  // 독립된 전체 정렬 기준
        mergeBack(actual, static_cast<int>(left.size()), right);
        assert(actual == expected);
        ++cases;
    }
    std::cout << "backward merge comparisons: " << cases << '\n';
}
